import { chromium } from '@playwright/test';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
const output = '.cache/gold-regression-paired';
await mkdir(output, {recursive:true});
const pairs = 40, frames = 256;
async function paired(a, {pairs, frames}) {
  const { XtermRenderer } = await import('http://127.0.0.1:5190/@fs/Users/betterclever/projects/wraith/.cache/gold-baseline/packages/wraith/src/xterm-renderer.ts');
  const old = XtermRenderer.prototype, current = Object.getPrototypeOf(a.renderer);
  const input=a.terminal._core._inputHandler, parser=input._parser;
  const slowParse=Object.getPrototypeOf(parser).parse, fastParse=parser.parse;
  const slowPrint=Object.getPrototypeOf(input).print, fastPrint=input.print;
  const modes=['baseline','input','overlay','combined'];
  const select = kind => {
    const fast=kind==='input'||kind==='combined', overlay=kind==='overlay'||kind==='combined';
    parser.parse=fast?fastParse:slowParse; input.print=fast?fastPrint:slowPrint;
    for (const name of ['pack','renderRows','fallbackReason']) a.renderer[name]=(overlay?current:old)[name];
  };
  const block=async(n)=>{ for(let i=0;i<n;i++){a.parse(a.inputs[i%8].bytes);a.draw();if((i+1)%32===0)await a.finish();} await a.finish(); };
  for(const mode of modes){select(mode);await block(512);}
  const results=[];
  for(let pair=0;pair<pairs;pair++){
    let order=modes.map((_,i)=>modes[(i+pair)%modes.length]);if(pair%2)order.reverse();
    for(const mode of order){select(mode);const submitted=a.submitted(),uploads=a.uploads(),start=performance.now();await block(frames);const elapsedMs=performance.now()-start;
      const count=a.submitted()-submitted;if(count!==frames)throw new Error('Lost submissions');
      const after=a.uploads();results.push({pair,mode,frames,count,elapsedMs,rate:frames*1000/elapsedMs,uploads:{cells:after.cells-uploads.cells,rowMap:after.rowMap-uploads.rowMap}});
    }
  }
  select('combined');a.assert();return results;
}
const result={date:new Date().toISOString(),pairs,frames,method:'Same terminal/device; original parser/print and baseline renderer methods toggled independently. All modes warm 512 updates. 40 rotated sets, 256 updates per block, fence every 32. Real submissions counted. No profiles concurrent.',sources:{},conditions:[]};
for(const file of ['packages/wraith/src/xterm-renderer.ts','packages/wraith/src/xterm-parser.js','packages/wraith/src/xterm-print.ts','.cache/gold-baseline/packages/wraith/src/xterm-renderer.ts'])result.sources[file]=createHash('sha256').update(await readFile(file)).digest('hex');
const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
try{
  for(const [workload,dpr] of [['append',1],['complex',2]]){
    const context=await browser.newContext({viewport:{width:2600,height:2100},deviceScaleFactor:dpr}),page=await context.newPage();
    const errors=[];page.on('pageerror',e=>errors.push(e.message));
    await page.route('**/compare.js*',async route=>{const response=await route.fetch();let body=await response.text();assert(body.includes('window.comparison = {'));body=`const paired=${paired.toString()};\n`+body.replace('window.comparison = {','window.comparison = { paired:options=>paired(active,options),');await route.fulfill({response,body});});
    await page.goto(`http://127.0.0.1:5173/compare.html?type=wraith&workload=${workload}`);await page.waitForFunction(()=>window.comparison?.ready);assert(await page.evaluate(()=>window.comparison.ready));
    const runs=await page.evaluate(options=>window.comparison.paired(options),{pairs,frames});assert.deepEqual(errors,[]);
    const median=xs=>[...xs].sort((a,b)=>a-b)[Math.floor(xs.length/2)];
    const summary=['baseline','input','overlay','combined'].map(mode=>{const samples=runs.filter(r=>r.mode===mode),ratios=samples.map(r=>r.rate/runs.find(b=>b.pair===r.pair&&b.mode==='baseline').rate).sort((a,b)=>a-b);return {mode,rate:median(samples.map(r=>r.rate)),pairedRatio:median(ratios),p10:ratios[4],p90:ratios[36]};});
    result.conditions.push({workload,dpr,runs,summary});await writeFile(output+'/runs.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({workload,dpr,summary},null,2));await page.evaluate(()=>window.comparison.dispose());await context.close();
  }
}finally{await browser.close();}
for(const [file,sha]of Object.entries(result.sources))assert.equal(createHash('sha256').update(await readFile(file)).digest('hex'),sha);
